import{_ as t,o as e,c as l,ae as r}from"./chunks/framework.BeMCGcrk.js";const b=JSON.parse('{"title":"科技股日报 2026年7月9日","description":"每日科技股动态速览","frontmatter":{"title":"科技股日报 2026年7月9日","date":"2026-07-09T00:00:00.000Z","description":"每日科技股动态速览"},"headers":[],"relativePath":"blog/2026-07-09-tech-stocks-daily.md","filePath":"blog/2026-07-09-tech-stocks-daily.md"}'),o={name:"blog/2026-07-09-tech-stocks-daily.md"};function i(h,a,d,n,s,c){return e(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="科技股日报-2026年7月9日" tabindex="-1">科技股日报 2026年7月9日 <a class="header-anchor" href="#科技股日报-2026年7月9日" aria-label="Permalink to &quot;科技股日报 2026年7月9日&quot;">​</a></h1><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日科技股市场关注的焦点集中在阿里巴巴、美团、小米三家公司。阿里股价暴涨14%成为最大亮点，美团面临监管新规而小米则在品牌建设方面有新动作。</p><hr><h2 id="阿里巴巴-baba-09988-hk" tabindex="-1">阿里巴巴 (BABA/09988.HK) <a class="header-anchor" href="#阿里巴巴-baba-09988-hk" aria-label="Permalink to &quot;阿里巴巴 (BABA/09988.HK)&quot;">​</a></h2><h3 id="股价表现" tabindex="-1">股价表现 <a class="header-anchor" href="#股价表现" aria-label="Permalink to &quot;股价表现&quot;">​</a></h3><p>阿里巴巴周三创下去年9月以来最大单日涨幅，股价盘中一度上涨<strong>13.8%</strong>。市场对其业绩前景的预期明显改善，推动资金重新流向此前表现落后的中国大型互联网企业。</p><h3 id="官方辟谣" tabindex="-1">官方辟谣 <a class="header-anchor" href="#官方辟谣" aria-label="Permalink to &quot;官方辟谣&quot;">​</a></h3><p>针对网传阿里首席科学家周靖人将离职的传闻，阿里巴巴回应称&quot;周靖人辞职&quot;纯属谣言。阿里方面表示将追究传播不实信息者的法律责任。</p><blockquote><p>过去数月，市场最担心阿里巴巴陷入&quot;补贴换份额、利润承压&quot;的恶性循环，此次大涨表明投资者对其基本面重拾信心。</p></blockquote><hr><h2 id="美团-3690-hk" tabindex="-1">美团 (3690.HK) <a class="header-anchor" href="#美团-3690-hk" aria-label="Permalink to &quot;美团 (3690.HK)&quot;">​</a></h2><h3 id="监管新规" tabindex="-1">监管新规 <a class="header-anchor" href="#监管新规" aria-label="Permalink to &quot;监管新规&quot;">​</a></h3><p>市场监管总局发布《外卖平台补贴行为规范十条(征求意见稿)》，美团坚决拥护，将认真学习并积极配合，推动各项规范要求落地见效。</p><p>新规要点：</p><ul><li>明确补贴行为边界</li><li>禁止长周期大规模补贴等非理性竞争</li><li>规范市场秩序</li></ul><h3 id="算法优化" tabindex="-1">算法优化 <a class="header-anchor" href="#算法优化" aria-label="Permalink to &quot;算法优化&quot;">​</a></h3><p>美团宣布将持续优化以下方面：</p><ul><li>计价算法</li><li>时长预估算法</li><li>路径规范算法</li><li>取消超时扣款</li><li>改进服务分规则</li><li>探索&quot;难送&quot;订单动态补偿</li></ul><hr><h2 id="小米-1810-hk" tabindex="-1">小米 (1810.HK) <a class="header-anchor" href="#小米-1810-hk" aria-label="Permalink to &quot;小米 (1810.HK)&quot;">​</a></h2><h3 id="人事调整" tabindex="-1">人事调整 <a class="header-anchor" href="#人事调整" aria-label="Permalink to &quot;人事调整&quot;">​</a></h3><p>小米中国区开启新一轮人事架构调整，覆盖汽车销交服、销售运营、电商、新零售等核心业务部门，多位核心管理人员岗位迎来变动。</p><h3 id="品牌建设" tabindex="-1">品牌建设 <a class="header-anchor" href="#品牌建设" aria-label="Permalink to &quot;品牌建设&quot;">​</a></h3><p>&quot;小米辟谣&quot;官方微博账号正式上线，这是小米集团官方辟谣阵地，在中央网信办违法和不良信息举报中心的指导下建立。</p><p>该账号将：</p><ul><li>发布小米全品牌辟谣声明</li><li>接收各类谣言线索反馈</li><li>通过法律手段维护自身合法商誉</li></ul><hr><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>公司</th><th>关键词</th><th>影响</th></tr></thead><tbody><tr><td>阿里巴巴</td><td>股价暴涨14%、辟谣</td><td>✅ 正面</td></tr><tr><td>美团</td><td>监管新规、算法优化</td><td>🟡 中性</td></tr><tr><td>小米</td><td>人事调整、辟谣上线</td><td>🟡 中性</td></tr></tbody></table><blockquote><p>风险提示：本文仅供参考，不构成投资建议。股市有风险，投资需谨慎。</p></blockquote><hr><p><em>更新时间：2026年7月9日</em></p>',33)])])}const p=t(o,[["render",i]]);export{b as __pageData,p as default};
